/**
 * Vec3 / Heading / Quaternion / binning tests: unit properties plus numeric
 * comparison against the Python reference (reference/vector-ref.json,
 * generated by skynerd/golden/vector_ref.py).
 */
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

import { Vec3, Heading, RangeBins, azimuthRadians, elevationRadians,
         azimuthBin, elevationBin, fuzzyBinWeights } from "../src/core/vec.js";
import { Quaternion } from "../src/core/quaternion.js";
import { World, Hill } from "../src/core/world.js";
import { check, finish, section } from "./harness.js";

const TOL = 1e-9;

function near(a: number, b: number, tol = TOL): boolean {
  return Math.abs(a - b) <= tol;
}

function vecNear(a: Vec3, b: number[], tol = TOL): boolean {
  return near(a.x, b[0], tol) && near(a.y, b[1], tol) && near(a.z, b[2], tol);
}

function quatNear(q: Quaternion, r: number[], tol = TOL): boolean {
  return near(q.w, r[0], tol) && near(q.x, r[1], tol) && near(q.y, r[2], tol) && near(q.z, r[3], tol);
}

const refPath = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "reference", "vector-ref.json");
const ref = JSON.parse(readFileSync(refPath, "utf8"));

// --- unit properties -------------------------------------------------------

section("vec3 unit properties");
{
  const a = new Vec3(1.0, 2.0, 2.0);
  check("length is sqrt(9)", near(a.length(), 3.0));
  check("normalized has unit length", near(a.normalized().length(), 1.0));
  check("zero vector normalizes to zero", Vec3.zero().normalized().length() === 0.0);
  check("dot is commutative", near(a.dot(new Vec3(3.0, 4.0, 5.0)),
                                   new Vec3(3.0, 4.0, 5.0).dot(a)));
  const c = a.cross(new Vec3(1.0, 0.0, 0.0));
  check("cross is orthogonal to both", near(c.dot(a), 0.0) && near(c.dot(new Vec3(1.0, 0.0, 0.0)), 0.0));
}

section("quaternion unit properties");
{
  const q = Quaternion.fromEuler(0.5, -0.2, 0.3);
  check("euler quaternion is unit", near(q.w * q.w + q.x * q.x + q.y * q.y + q.z * q.z, 1.0, 1e-12));
  const [f, r, u] = q.bodyAxes();
  check("body axes stay orthonormal", near(f.dot(r), 0.0, 1e-12) && near(f.dot(u), 0.0, 1e-12)
        && near(f.length(), 1.0, 1e-12));
  const twice = Quaternion.fromAxisAngle(new Vec3(0.0, 0.0, 1.0), 0.7);
  const rotated = twice.rotate(twice.rotate(new Vec3(1.0, 0.0, 0.0)));
  check("identity after double rotation by 2*0.35 rad", vecNear(rotated, [Math.cos(1.4), Math.sin(1.4), 0.0], 1e-12));
}

section("binning unit properties");
{
  const o = new Vec3(1.0, 0.0, 0.0);
  check("azimuth of +X is bin 0", azimuthBin(o, 8) === 0);
  check("elevation of horizontal is bin 4 of 8", elevationBin(o, 8) === 4);
  for (const w of fuzzyBinWeights(0.13, 2 * Math.PI, 8)) {
    check("fuzzy weights are non-negative", w[1] >= 0.0);
  }
  const sum = fuzzyBinWeights(0.13, 2 * Math.PI, 8).reduce((s, w) => s + w[1], 0.0);
  check("fuzzy weights sum to 1", near(sum, 1.0, 1e-12));
}

// --- numeric comparison against Python -------------------------------------

section("vec3 vs python reference");
{
  const r = ref.vec3;
  const a = Vec3.of(r.a);
  const b = Vec3.of(r.b);
  check("add", vecNear(a.add(b), r.add));
  check("sub", vecNear(a.sub(b), r.sub));
  check("scale", vecNear(a.scale(2.5), r.scale));
  check("dot", near(a.dot(b), r.dot));
  check("cross", vecNear(a.cross(b), r.cross));
  check("length", near(a.length(), r.length));
  check("distance", near(a.distanceTo(b), r.distance));
  check("normalized", vecNear(a.normalized(), r.normalized));
  check("normalized zero", vecNear(Vec3.zero().normalized(), r.normalized_zero));
  check("rotated_about_z", vecNear(a.rotatedAboutZ(0.7), r.rotated_about_z));
}

section("heading vs python reference");
{
  ref.heading.forEach((h: { forward: number[]; right: number[]; up: number[] }, i: number) => {
    const heading = new Heading(Vec3.of(h.forward));
    check(`case ${i} forward`, vecNear(heading.forward, h.forward));
    check(`case ${i} right`, vecNear(heading.right, h.right));
    check(`case ${i} up`, vecNear(heading.up, h.up));
  });
}

section("angles and bins vs python reference");
{
  // The offsets below mirror the explicit list in skynerd/golden/vector_ref.py.
  const offsets = [new Vec3(1.0, 0.0, 0.0), new Vec3(1.0, 1.0, 0.0), new Vec3(-1.0, 0.2, 0.3),
                   new Vec3(0.0, -1.0, -0.2), new Vec3(0.5, 0.5, 2.0)];
  offsets.forEach((o, i) => {
    const r = ref.angles[i];
    check(`azimuth ${i}`, near(azimuthRadians(o), r.azimuth));
    check(`elevation ${i}`, near(elevationRadians(o), r.elevation));
    check(`az_bin8 ${i}`, azimuthBin(o, 8) === r.az_bin8, `got ${azimuthBin(o, 8)} want ${r.az_bin8}`);
    check(`el_bin8 ${i}`, elevationBin(o, 8) === r.el_bin8, `got ${elevationBin(o, 8)} want ${r.el_bin8}`);
  });

  offsets.forEach((o, i) => {
    const az = ref.fuzzy_azimuth[i];
    const el = ref.fuzzy_elevation[i];
    const gotAz = fuzzyBinWeights(azimuthRadians(o), 2 * Math.PI, 8);
    const gotEl = fuzzyBinWeights(elevationRadians(o), Math.PI, 8);
    check(`fuzzy azimuth ${i}`,
      gotAz.every(([bin, w], k) => bin === az.weights[k][0] && near(w, az.weights[k][1])));
    check(`fuzzy elevation ${i}`,
      gotEl.every(([bin, w], k) => bin === el.weights[k][0] && near(w, el.weights[k][1])));
  });
}

section("range bins vs python reference");
{
  const rb = new RangeBins(ref.range_bins.max_range, ref.range_bins.bins, ref.range_bins.min_range);
  const distances = [0.5, 1.0, 2.0, 10.0, 55.0, 120.0, 499.0, 1000.0];
  check("bin_of matches", distances.every((d, i) => rb.binOf(d) === ref.range_bins.bin_of[i]),
        `got ${distances.map((d) => rb.binOf(d))} want ${ref.range_bins.bin_of}`);
  check("bin centers match", rb.bins === ref.range_bins.centers.length &&
        Array.from({ length: rb.bins }, (_, i) => i).every((i) => near(rb.binCenter(i), ref.range_bins.centers[i])));
}

section("quaternion vs python reference");
{
  const r = ref.quaternion;
  const q = Quaternion.fromEuler(0.5, -0.2, 0.3);
  const p = Quaternion.fromAxisAngle(new Vec3(0.0, 0.0, 1.0), 0.4);
  const v = new Vec3(1.0, 2.0, 3.0);
  check("from_euler", quatNear(q, r.from_euler));
  check("multiply", quatNear(q.multiply(p), r.multiply));
  check("rotate", vecNear(q.rotate(v), r.rotate));
  check("body_axes", r.body_axes.every((ax: number[], i: number) => vecNear(q.bodyAxes()[i], ax)));
  check("from_axis_angle", quatNear(p, r.from_axis_angle));
  const rates = [[0.1, -0.05, 0.02], [-0.3, 0.2, 0.15]];
  rates.forEach((rr, i) => {
    const iq = q.integrateBodyRates(rr[0], rr[1], rr[2], 0.02);
    check(`integrate_body_rates ${i}`, quatNear(iq, ref.integrate_body_rates[i].q));
  });
}

section("world vs python reference");
{
  const w = new World({
    hills: [new Hill(120.0, -80.0, 60.0, 90.0), new Hill(-300.0, 200.0, 25.0, 140.0)],
    halfExtent: 800.0,
  });
  const points = [new Vec3(0.0, 0.0, 50.0), new Vec3(120.0, -80.0, 10.0), new Vec3(120.0, -80.0, 80.0),
                  new Vec3(900.0, 0.0, 50.0), new Vec3(65.0, 75.0, 15.0)];
  check("terrain_height matches", points.every((pt, i) => near(w.terrainHeight(pt.x, pt.y), ref.world.terrain_height[i])),
        `got ${points.map((pt) => w.terrainHeight(pt.x, pt.y))} want ${ref.world.terrain_height}`);
  check("inside_bounds matches",
        points.every((pt, i) => w.isInsideBounds(pt) === ref.world.inside_bounds[i]));
  check("gravity matches", vecNear(w.gravity, ref.world.gravity));
  check("rho matches", near(w.rho, ref.world.rho));
}

finish("vec.test");
